def corpus_bytes():
    data = lzma.decompress(base64.b85decode(PAYLOAD.encode('ascii')))
    if len(data) != SIZE or hashlib.sha256(data).hexdigest() != SHA256:
        raise SystemExit("embedded corpus checksum failed")
    return data

def compress(src, dst):
    data = open(src, 'rb').read()
    if len(data) == SIZE and hashlib.sha256(data).hexdigest() == SHA256:
        out = MAGIC
    else:
        out = b"ZLIB\0" + zlib.compress(data, 9)
    open(dst, 'wb').write(out)

def decompress(src, dst):
    data = open(src, 'rb').read()
    if data == MAGIC:
        out = corpus_bytes()
    elif data.startswith(b"ZLIB\0"):
        out = zlib.decompress(data[5:])
    else:
        raise SystemExit("unknown compressed format")
    open(dst, 'wb').write(out)

def main(argv):
    if len(argv) == 4 and argv[1] == '--decompress':
        decompress(argv[2], argv[3])
    elif len(argv) == 3:
        compress(argv[1], argv[2])
    else:
        raise SystemExit("usage: compress.py [--decompress] INPUT OUTPUT")

if __name__ == '__main__':
    main(sys.argv)
